def main():
    try:
        app = ReportSplitter()
        app.mainloop()
    except Exception as exc:
        import traceback
        try:
            root = tk.Tk(); root.withdraw()
            messagebox.showerror("Startup Error",
                f"The app failed to start:\n\n{exc}\n\n"
                f"{traceback.format_exc()[-800:]}")
            root.destroy()
        except Exception:
            pass


if __name__ == "__main__":
    main()
